-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.release_json_text(j jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select coalesce(string_agg(public.release_text(v #>> '{}'), ' | '), '')
    from jsonb_path_query(coalesce(j, 'null'::jsonb),
                          'strict $.** ? (@.type() != "object" && @.type() != "array" && @.type() != "null")') as v;
$function$;
